func:
// ============================================================
// Anker MAX AC – Optimale Einbindung neben SolarEdge + LG Chem
// ------------------------------------------------------------
// Der Anker-Speicher kann nicht mit SolarEdge/LG Chem kommunizieren
// und regelt sich nicht automatisch auf PV-Ueberschuss ein. Dieser
// Knoten liest deshalb den aktuellen Anlagenzustand aus dem lokalen
// Home-Assistant-Zustandscache und entscheidet, ob der Anker gerade
// laden, entladen oder nichts tun soll. SolarEdge/LG Chem werden
// dabei NICHT gesteuert, nur ausgelesen - ihre eigene
// Eigenverbrauchsregelung hat immer Vorrang.
//
// Steuerkonzept (z.B. Anker SOLIX Solarbank Max AC ueber ha-anker-solix):
// Das Geraet hat einen "Drittanbieter-Steuerung"-Modus (third_party_control)
// sowie eine Richtung (charge/discharge, ueber ein select-Entity) + eine
// Ziel-Watt-Zahl ("Netzleistung", ueber ein number-Entity). ACHTUNG: Die in
// der App/HA-UI angezeigten deutschen Texte sind nur Anzeigenamen - an
// select.select_option muessen die englischen Rohwerte gesendet werden
// (im Zweifel unter Entwicklerwerkzeuge -> Zustaende -> Attribut "options"
// nachsehen). Falls deine Anker-Integration ein anderes Steuerkonzept hat
// (z.B. getrennte Lade-/Entladeleistungs-Limits), muss die Zuordnung der
// drei Service-Call-Knoten entsprechend angepasst werden.
// ============================================================

// ---------- 1) KONFIGURATION: Entity-IDs anpassen! ----------
const ENTITIES = {
    gridPower: 'sensor.solaredge_m1_ac_power',          // W, + = Netzbezug, - = Einspeisung
    gridPowerSign: -1,                                   // bei dieser Installation bestaetigt umgekehrtes Vorzeichen (negativ = Bezug, positiv = Einspeisung)
    lgSoc: 'sensor.solaredge_battery_state_of_energy',   // % Ladestand LG Chem (ueber SolarEdge/StorEdge)
    lgPower: 'sensor.solaredge_battery_dc_power',        // W, + = LG Chem laedt, - = LG Chem entlaedt
    ankerSoc: 'sensor.anker_solarbank_state_of_charge',  // % Ladestand Anker MAX AC
};

// ---------- 2) GRENZWERTE / VERHALTEN ------------------------
const LIMITS = {
    ankerMinSoc: 10,                 // % - nie unter diesen Wert entladen (Zellschutz; zusaetzlich geraeteseitig als "Entladegrenze" setzen)
    ankerMaxSoc: 95,                 // % - nie ueber diesen Wert laden (Zellschutz; zusaetzlich geraeteseitig als "Ladeobergrenze" setzen)
    ankerMaxChargePower: 1200,       // W - siehe Datenblatt Anker MAX AC anpassen
    ankerMaxDischargePower: 1800,    // W - siehe Datenblatt Anker MAX AC anpassen
    lgFullSoc: 95,                   // % - ab hier gilt LG Chem als "voll genug"; Ueberschuss darf zum Anker
    lgEmptySoc: 20,                  // % - grober Richtwert "leer genug" (grosszuegige Obergrenze); entscheidend ist lgIdlePowerW
    lgIdlePowerW: 50,                // W - LG Chem gilt erst als gesaettigt, wenn Lade-/Entladeleistung darunter liegt
    deadbandW: 60,                   // W - kleinere Ueberschuesse/Defizite werden ignoriert (Anti-Flattern)
    minCommandIntervalMs: 90 * 1000, // ms - Mindestabstand zwischen zwei Befehlen (Cloud-API schonen)
    minPowerDeltaToResend: 50,       // W - Befehl nur wiederholen, wenn sich Zielwert deutlich aendert
    forceResendMs: 10 * 60 * 1000,   // ms - Befehl trotzdem regelmaessig auffrischen (Absicherung)
};

// ---------- 3) HILFSFUNKTIONEN --------------------------------
function getState(entityId) {
    const ha = global.get('homeassistant');
    const store = ha && ha.homeAssistant ? ha.homeAssistant.states : undefined;
    const st = store ? store[entityId] : undefined;
    if (!st || st.state === 'unavailable' || st.state === 'unknown') return undefined;
    const num = Number(st.state);
    return Number.isNaN(num) ? undefined : num;
}

function clamp(v, min, max) {
    return Math.max(min, Math.min(max, v));
}

// ---------- 4) AKTUELLE WERTE LESEN ---------------------------
const raw = {
    gridPower: getState(ENTITIES.gridPower),
    lgSoc: getState(ENTITIES.lgSoc),
    lgPower: getState(ENTITIES.lgPower),
    ankerSoc: getState(ENTITIES.ankerSoc),
};

if (raw.gridPower === undefined || raw.lgSoc === undefined || raw.lgPower === undefined || raw.ankerSoc === undefined) {
    const errMsg = { payload: 'Anker-Steuerung: Pflicht-Sensor(en) nicht verfuegbar - keine Aktion ausgefuehrt.', details: raw };
    node.warn(errMsg.payload);
    node.status({ fill: 'red', shape: 'ring', text: 'Sensor fehlt' });
    return [null, null, null, null, errMsg, null];
}

const gridPower = raw.gridPower * ENTITIES.gridPowerSign; // + Bezug / - Einspeisung
const surplus = -gridPower; // > 0 => PV-Ueberschuss vorhanden
const deficit = gridPower;  // > 0 => Netzbezug

// ---------- 5) ENTSCHEIDUNG ------------------------------------
let action = 'idle';
let chargeTarget = 0;
let dischargeTarget = 0;

const canCharge = raw.ankerSoc < LIMITS.ankerMaxSoc;
const canDischarge = raw.ankerSoc > LIMITS.ankerMinSoc;

// LG Chem gilt nur dann als "gesaettigt", wenn zusaetzlich zum SOC-Schwellenwert
// auch die tatsaechliche Lade-/Entladeleistung nahe Null ist - sonst laedt/entlaedt
// SolarEdge den Speicher noch aktiv, und der Anker wuerde unnoetig konkurrieren.
const lgSaturatedFull = raw.lgSoc >= LIMITS.lgFullSoc && raw.lgPower <= LIMITS.lgIdlePowerW;
const lgSaturatedEmpty = raw.lgSoc <= LIMITS.lgEmptySoc && raw.lgPower >= -LIMITS.lgIdlePowerW;

if (surplus > LIMITS.deadbandW && lgSaturatedFull && canCharge) {
    // LG Chem ist voll und laedt nicht mehr, es gibt noch Ueberschuss -> Anker laden
    action = 'charge';
    chargeTarget = clamp(surplus, 0, LIMITS.ankerMaxChargePower);
} else if (deficit > LIMITS.deadbandW && lgSaturatedEmpty && canDischarge) {
    // LG Chem ist leer und entlaedt nicht mehr, es wird noch importiert -> Anker entladen
    action = 'discharge';
    dischargeTarget = clamp(deficit, 0, LIMITS.ankerMaxDischargePower);
}

// Sicherheits-Hardstops (Zellschutz geht immer vor)
if (!canDischarge) dischargeTarget = 0;
if (!canCharge) chargeTarget = 0;

const targetDirection = action === 'charge' ? 'charge' : 'discharge'; // bei 'idle' irrelevant, da Power=0
const targetPower = action === 'charge' ? chargeTarget : (action === 'discharge' ? dischargeTarget : 0);

// ---------- 6) HYSTERESE / RATE LIMITING -----------------------
const prev = context.get('state') || { action: 'idle', targetPower: 0, ts: 0 };
const now = Date.now();
const elapsed = now - prev.ts;

const actionChanged = action !== prev.action;
const powerDelta = Math.abs(targetPower - prev.targetPower);
const significantChange = powerDelta >= LIMITS.minPowerDeltaToResend;
const isSafetyOverride = (prev.action === 'discharge' && !canDischarge) || (prev.action === 'charge' && !canCharge);
const dueForRefresh = elapsed >= LIMITS.forceResendMs;

let shouldSend = actionChanged || significantChange || isSafetyOverride || dueForRefresh;
if (shouldSend && elapsed < LIMITS.minCommandIntervalMs && !isSafetyOverride) {
    shouldSend = false; // Mindestabstand zwischen Cloud-Befehlen noch nicht erreicht
}

let modeMsg = null;
let directionMsg = null;
let powerMsg = null;

if (shouldSend) {
    context.set('state', { action, targetPower, ts: now });

    modeMsg = { payload: { mode: 'third_party_control' } };
    directionMsg = { payload: { direction: targetDirection } };
    powerMsg = { payload: { power: Math.round(targetPower) } };
}

const statusMsg = {
    payload: {
        action,
        targetDirection,
        targetPower: Math.round(targetPower),
        gridPower,
        lgSoc: raw.lgSoc,
        ankerSoc: raw.ankerSoc,
        befehlGesendet: shouldSend,
        zeitstempel: new Date(now).toISOString(),
    },
};

node.status({
    fill: action === 'idle' ? 'grey' : 'green',
    shape: shouldSend ? 'dot' : 'ring',
    text: action + (action !== 'idle' ? ' ' + Math.round(targetPower) + 'W' : ''),
});

const clearErrMsg = { payload: 'anker_control_error' };

return [modeMsg, directionMsg, powerMsg, statusMsg, null, clearErrMsg];
